+            float[] response = new float[vectorToBuild.size()];
+            int i = 0;
+            for (Float f : vectorToBuild) {
+                response[i++] = f;
+            }
+            listener.onResponse(response);
+        }
+
+        @Override
+        public boolean equals(Object o) {
+            if (this == o) return true;
+            if (o == null || getClass() != o.getClass()) return false;
